mapper.update:
UPDATE member
SET MemberPoints = COALESCE(MemberPoints, 0) + #{memberPoints}
WHERE MemberId = #{memberId}

UPDATE member
SET MemberPoints = COALESCE(MemberPoints, 0) - #{memberPoints}
WHERE MemberId = #{memberId}

UPDATE member
SET MemberCartCount = COALESCE(memberCartCount, 0) + 1
WHERE MemberId = #{memberId}

UPDATE member
SET MemberWishCount = COALESCE(memberWishCount, 0) + 1
WHERE MemberId = #{memberId}
